      f: "Transit Gateway connects VPCs and on-premises networks; it does not accelerate end-user traffic.",
      g: "Cross-zone load balancing distributes traffic among AZs within one Region; it does not route between Regions.",
      h: "PrivateLink provides private access to services within AWS; it does not serve public internet users.",
