    id: "tech87",
    domain: "cloud-technology-and-services",
    text: "Which TWO of the following statements about AWS end-user computing and communication services are correct?",
    options: [
      { id: "a", text: "Amazon WorkSpaces provides managed, persistent virtual desktops (Desktop-as-a-Service) that users access from many device types" },
      { id: "b", text: "Amazon Connect is a service for building physical network connections from on-premises data centers to AWS" },
      { id: "c", text: "Amazon AppStream 2.0 streams individual desktop applications to users' browsers without installing them locally" },
      { id: "d", text: "AWS End User Messaging is a managed relational database for storing customer contact information" },
      { id: "e", text: "Amazon WorkSpaces requires each user to install Windows Server on their local device before connecting" },
      { id: "f", text: "Amazon Connect provides managed Linux virtual desktops for remote employees" },
      { id: "g", text: "Amazon AppStream 2.0 is a content delivery network for streaming video to global audiences" },
      { id: "h", text: "Amazon WorkSpaces Secure Browser is a managed SFTP file transfer service" },
    ],
    correctOptionIds: ["a", "c"],
    explanation: "WorkSpaces delivers full virtual desktops and AppStream 2.0 streams applications to browsers; Amazon Connect is a cloud contact center service and AWS End User Messaging is a customer messaging service.",
    optionRationale: {
      a: "WorkSpaces is a fully managed Desktop-as-a-Service offering that provisions Windows or Linux desktops accessible from laptops, tablets, and thin clients.",
      b: "Amazon Connect is an omnichannel cloud contact center for voice and chat; AWS Direct Connect is the physical network connection service.",
      c: "AppStream 2.0 is an application streaming service that delivers desktop applications securely to any web browser without local installation.",
      d: "AWS End User Messaging (the SMS, push, and voice channels formerly part of Amazon Pinpoint) sends messages to customers; it is not a database. Pinpoint's campaign features reach end of support on October 30, 2026, with Amazon Connect recommended for outbound engagement.",
      e: "WorkSpaces desktops run in AWS and are accessed from a lightweight client or browser; nothing server-grade is installed locally.",
      f: "Amazon Connect is a cloud contact center service; virtual desktops are provided by WorkSpaces.",
      g: "AppStream 2.0 streams desktop applications, not video content; CloudFront is the content delivery network.",
      h: "WorkSpaces Secure Browser provides secure browser access to internal web apps; SFTP endpoints come from AWS Transfer Family.",
    },
    referenceUrl: "https://docs.aws.amazon.com/workspaces/latest/adminguide/amazon-workspaces.html",
