    id: "tech97",
    domain: "cloud-technology-and-services",
    text: "A streaming service has licensing agreements that require users in Germany to be served content from an endpoint in Frankfurt and users in Japan from an endpoint in Tokyo, based on the country the user is in, regardless of which endpoint has lower latency. Which Amazon Route 53 routing policy should be used?",
    options: [
      { id: "a", text: "Geolocation routing" },
      { id: "b", text: "Latency-based routing" },
      { id: "c", text: "Simple routing" },
      { id: "d", text: "Weighted routing" },
      { id: "e", text: "Failover routing" },
      { id: "f", text: "Multivalue answer routing" },
      { id: "g", text: "Geoproximity routing" },
      { id: "h", text: "Amazon Route 53 Resolver" },
    ],
    correctOptionIds: ["a"],
    explanation: "Geolocation routing returns records based on the geographic location the DNS query originates from (continent, country, or US state), which is the right tool for content licensing and localization requirements.",
    optionRationale: {
      a: "Geolocation routing maps a user's country to a specific endpoint, meeting the licensing requirement exactly.",
      b: "Latency-based routing picks the fastest endpoint, which could send a German user to a non-German Region.",
      c: "Simple routing returns one record set with no location awareness.",
      d: "Weighted routing splits traffic by percentage, not by user location.",
      e: "Failover routing only chooses between a primary and a secondary based on health, not on the user's country.",
      f: "Multivalue answer returns up to eight healthy records at random; it does not consider where the user is located.",
      g: "Geoproximity routes based on distance to your resources plus a bias, so a user might be sent to the nearer endpoint rather than the one required by their country.",
      h: "Route 53 Resolver handles DNS resolution between VPCs and on-premises networks; it is not a routing policy.",
    },
    referenceUrl: "https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/routing-policy-geo.html",
