    text: "A team maintains its production environment with AWS CloudFormation. Before applying an updated template, it wants to see exactly which resources will be added, modified, or replaced, so that it can catch an accidental database replacement before it happens. Which CloudFormation feature should the team use?",
    options: [
      { id: "a", text: "Change sets" },
      { id: "b", text: "Stack outputs" },
      { id: "c", text: "Nested stacks" },
      { id: "d", text: "Stack termination protection" },
      { id: "e", text: "Drift detection" },
      { id: "f", text: "Stack policies" },
      { id: "g", text: "StackSets" },
      { id: "h", text: "Rollback triggers" },
    ],
    correctOptionIds: ["a"],
    explanation: "A change set previews how proposed template or parameter changes will affect the running stack, listing each resource action (Add, Modify, Remove) and whether a modification requires replacement, before you choose to execute it.",
    optionRationale: {
      a: "Change sets are the CloudFormation mechanism for reviewing the impact of an update before it is applied.",
      b: "Outputs export values from a stack; they do not preview changes.",
      c: "Nested stacks organize templates into reusable components but do not preview updates.",
      d: "Termination protection prevents the whole stack from being deleted; it does not show what an update will change.",
      e: "Drift detection compares a stack's actual resources with its template after deployment; it does not preview an upcoming update.",
      f: "A stack policy blocks updates to protected resources but does not show what an update would change.",
      g: "StackSets deploys stacks to multiple accounts and Regions; it does not preview resource-level changes.",
      h: "Rollback triggers monitor CloudWatch alarms during an update and roll back on breach; they do not show the planned changes beforehand.",
    },
    referenceUrl: "https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/using-cfn-updating-stacks-changesets.html",
    referenceLabel: "Updating Stacks Using Change Sets",
    consoleUrl: "https://console.aws.amazon.com/cloudformation/home#/stacks",
    consoleLabel: "CloudFormation > Stacks",
    diagram: "flowchart LR\n  Tmpl[Updated template] --> CS[Create change set]\n  CS --> Review{Review: Add / Modify / Replace}\n  Review -->|safe| Exec[Execute change set]\n  Review -->|replacement of DB| Abort[Fix template first]",
