      f: "Rekognition analyzes image content such as labels and faces; it does not resize or produce thumbnails.",
      g: "An always-on EC2 instance incurs cost even when nobody uploads and a five-minute cron does not meet the within-seconds requirement.",
      h: "An hourly batch job is too slow for a thumbnail that must appear within seconds of upload.",
