    id: "tech114",
    domain: "cloud-technology-and-services",
    text: "A consortium of banks wants to share a tamper-evident transaction ledger across multiple independent organizations, with no single party in control, using the open-source Hyperledger Fabric framework. They do not want to provision or manage the blockchain network's peer nodes themselves. Which AWS service best meets this requirement?",
    options: [
      { id: "a", text: "Amazon Managed Blockchain" },
      { id: "b", text: "Amazon RDS for PostgreSQL" },
      { id: "c", text: "Amazon DynamoDB" },
      { id: "d", text: "Amazon Neptune" },
      { id: "e", text: "Amazon Aurora" },
      { id: "f", text: "AWS Key Management Service (KMS)" },
      { id: "g", text: "Amazon Keyspaces (for Apache Cassandra)" },
      { id: "h", text: "AWS CloudHSM" },
    ],
    correctOptionIds: ["a"],
    explanation: "Amazon Managed Blockchain is a fully managed service for creating and managing scalable blockchain networks using Hyperledger Fabric, so multiple parties can transact and share a verifiable ledger without a central authority and without running their own nodes. Note that Amazon QLDB, the single-authority ledger database that used to appear in this space, reached end of support on July 31, 2025; AWS recommended migrating QLDB ledgers to Amazon Aurora PostgreSQL.",
    optionRationale: {
      a: "Managed Blockchain provisions the network, member nodes, and Hyperledger Fabric components so a multi-party consortium can share a decentralized ledger.",
      b: "RDS is a general-purpose relational database owned by one party; it has no multi-organization consensus or built-in tamper evidence.",
      c: "DynamoDB is a NoSQL key-value store without a shared, verifiable multi-party ledger.",
      d: "Neptune is a managed graph database for highly connected data, not a blockchain or ledger service.",
      e: "Aurora is a relational database owned and controlled by a single account; it does not provide a decentralized multi-party blockchain network.",
      f: "KMS manages encryption keys; it does not run Hyperledger Fabric networks or ledgers.",
      g: "Keyspaces is a Cassandra-compatible database under one owner's control, not a shared blockchain.",
      h: "CloudHSM provides dedicated hardware security modules for key storage; it is not a blockchain service.",
    },
    referenceUrl: "https://docs.aws.amazon.com/managed-blockchain/latest/hyperledger-fabric-dev/what-is-managed-blockchain.html",
