    diagram: "flowchart LR\n  BankA[Bank A member] --> Net[Managed Blockchain network - Hyperledger Fabric]\n  BankB[Bank B member] --> Net\n  BankC[Bank C member] --> Net\n  Net --> Ledger[Shared tamper-evident ledger]",
