    text: "An architect is evaluating AWS infrastructure options for placing compute closer to end users. Which TWO statements are correct?",
    options: [
      { id: "a", text: "AWS Local Zones extend a Region into large metropolitan areas so latency-sensitive applications can run close to users" },
      { id: "b", text: "AWS Wavelength embeds AWS compute and storage within telecommunications providers' 5G networks to minimize mobile latency" },
      { id: "c", text: "AWS Outposts is a fully managed offering that provides a new AWS Region within any city on request" },
      { id: "d", text: "Edge locations run customer EC2 instances and RDS databases at the network edge" },
      { id: "e", text: "Availability Zones are located inside customer data centers" },
      { id: "f", text: "AWS Outposts racks are hosted inside AWS Regions rather than at a customer's own facility" },
      { id: "g", text: "AWS Local Zones are installed inside customer-owned data centers" },
      { id: "h", text: "AWS Wavelength Zones replace Availability Zones as the recommended location for RDS Multi-AZ databases" },
    ],
    correctOptionIds: ["a", "b"],
    explanation: "Local Zones place compute, storage, and database services in metro areas near large populations, while Wavelength Zones sit inside 5G carrier networks for ultra-low-latency mobile applications. Outposts brings AWS hardware to a customer site, edge locations serve CloudFront and Route 53, and AZs are AWS-operated data centers.",
    optionRationale: {
      a: "Local Zones are extensions of a parent Region deployed in metropolitan areas for single-digit millisecond latency.",
      b: "Wavelength Zones are deployed inside telecom providers' 5G networks so mobile traffic does not leave the carrier network.",
      c: "Outposts installs AWS-managed racks in the customer's own facility; it does not create a Region.",
      d: "Edge locations cache content for CloudFront and answer Route 53 queries; they do not host EC2 or RDS.",
      e: "Availability Zones are AWS-owned facilities, not customer data centers.",
      f: "Outposts are physically installed at the customer's site or colocation facility and managed by AWS from there.",
      g: "Local Zones are AWS-owned infrastructure in metro areas; customer-site infrastructure is Outposts.",
      h: "Wavelength Zones host a limited set of services for ultra-low-latency 5G apps; databases like RDS Multi-AZ remain in Regional Availability Zones.",
    },
    referenceUrl: "https://aws.amazon.com/about-aws/global-infrastructure/localzones/",
