    consoleLabel: "EFS > File systems",
    diagram: "flowchart LR\n  New[New file written] --> Std[EFS Standard storage]\n  Std -->|not accessed for 30 days| IA[EFS Infrequent Access]\n  IA -->|accessed again| Std\n  App[Application mount path] --> Std\n  App --> IA",
