    id: "tech160",
    domain: "cloud-technology-and-services",
    text: "A company's employees work remotely from home and coffee shops. They need secure, encrypted access from their laptops to internal applications running in an Amazon VPC and, through it, to the on-premises network. The company does not want to run and patch its own VPN servers. Which AWS service should it use?",
    options: [
      { id: "a", text: "AWS Client VPN" },
      { id: "b", text: "AWS Site-to-Site VPN" },
      { id: "c", text: "AWS Direct Connect" },
      { id: "d", text: "Amazon VPC peering" },
      { id: "e", text: "AWS Transit Gateway" },
      { id: "f", text: "Amazon WorkSpaces" },
      { id: "g", text: "AWS PrivateLink" },
      { id: "h", text: "An OpenVPN server on an EC2 instance" },
    ],
    correctOptionIds: ["a"],
    explanation: "AWS Client VPN is a managed, elastic, OpenVPN-based client VPN service. Individual users connect from their devices to a Client VPN endpoint associated with the VPC and can reach VPC resources, peered networks, and on-premises networks, with authentication through Active Directory, SAML single sign-on, or certificates.",
    optionRationale: {
      a: "Client VPN provides managed remote-user access from laptops to a VPC and connected networks without customer-managed VPN servers.",
      b: "Site-to-Site VPN connects an entire office or data center network to a VPC through a customer gateway device, not individual roaming users.",
      c: "Direct Connect is a dedicated physical link from a data center or colocation facility; it is not for remote laptops.",
      d: "VPC peering connects two VPCs; it does not provide user access from the internet.",
      e: "Transit Gateway interconnects VPCs and on-premises networks; it does not terminate individual user VPN clients.",
      f: "WorkSpaces provides virtual desktops; it is not a VPN for laptops to reach VPC resources.",
      g: "PrivateLink exposes services privately between VPCs; it does not provide remote user VPN access.",
      h: "Running OpenVPN on EC2 means the company must patch and scale its own VPN servers, which it wants to avoid.",
    },
    referenceUrl: "https://docs.aws.amazon.com/vpn/latest/clientvpn-admin/what-is.html",
