    diagram: "flowchart LR\n  Laptop[Remote employee laptop] -->|TLS VPN tunnel| CVPN[AWS Client VPN endpoint]\n  CVPN --> VPC[Private applications in VPC]\n  VPC --> OnPrem[On-premises network via Site-to-Site VPN]",
