    text: "A hedge fund's data scientists want to enrich their models with third-party datasets such as weather history, demographic statistics, and financial market data. They want to find, subscribe to, and receive these datasets directly into Amazon S3 from providers, with updates delivered automatically as the providers publish new revisions. Which AWS service should they use?",
