      d: "Route 53 is a DNS and domain service; it does not inventory or group AWS resources.",
      e: "Service Quotas shows and requests limits for services; it does not list your individual resources.",
      f: "Inventory collects software and configuration data from managed instances; it is not a cross-Region resource search.",
