    text: "A retailer wants to set up a cloud-based customer contact center within days. Agents should handle inbound phone calls and web chat from a browser, callers should be greeted by an interactive voice menu, and managers need call recordings and real-time queue metrics. Which AWS service provides this as a managed offering?",
