    text: "A company suspects that many of its EC2 instances, EBS volumes, and Lambda functions are over-provisioned. It wants a service that analyzes historical CloudWatch utilization metrics with machine learning and recommends specific alternative instance types, volume configurations, and memory sizes, along with projected performance risk and savings. Which service provides this?",
