    explanation: "AWS Compute Optimizer analyzes the configuration and utilization metrics of EC2 instances, Auto Scaling groups, EBS volumes, Lambda functions, ECS services on Fargate, and commercial database engines on RDS. Using machine learning it classifies resources as under-provisioned, over-provisioned, or optimized and recommends specific alternatives with estimated monthly savings and performance risk. Recommendations can also be viewed in Cost Optimization Hub.",
