    id: "tech256",
    domain: "cloud-technology-and-services",
    text: "A new engineer wants to understand the different ways to create and manage AWS resources. Which TWO statements about the ways of interacting with AWS services are correct? (Select TWO.)",
    options: [
      { id: "a", text: "The AWS Command Line Interface (AWS CLI) lets you control services from a terminal and script repeatable operations" },
      { id: "b", text: "AWS Software Development Kits (SDKs) let application code in languages such as Python, Java, and JavaScript call AWS APIs directly" },
      { id: "c", text: "The AWS Management Console is the only interface that can create resources; the CLI and SDKs are read-only" },
      { id: "d", text: "The AWS CLI can be used only from inside an EC2 instance" },
      { id: "e", text: "Infrastructure as code tools such as CloudFormation bypass the AWS APIs and modify resources directly" },
      { id: "f", text: "Each SDK uses a different set of APIs that is unavailable to the CLI" },
      { id: "g", text: "AWS CloudShell requires you to install and configure the CLI manually before use" },
      { id: "h", text: "The AWS Management Console cannot be used from a mobile device" },
    ],
    correctOptionIds: ["a", "b"],
    explanation: "Every AWS service exposes an API, and the console, CLI, SDKs, and infrastructure as code tools are all different clients of those same APIs. The AWS CLI is a unified command-line tool for scripting and automation from any machine with credentials, including laptops, CI servers, and CloudShell (where it is preinstalled). SDKs wrap the APIs in language-native libraries so applications can call services programmatically. The AWS Console Mobile Application also provides console access from phones.",
    optionRationale: {
      a: "Correct. The CLI provides full control of services from a terminal and is ideal for scripting.",
      b: "Correct. SDKs let application code call AWS APIs in many programming languages.",
      c: "The CLI and SDKs can create, modify, and delete resources just like the console.",
      d: "The CLI runs anywhere with network access and credentials, not only on EC2.",
      e: "CloudFormation calls the same AWS APIs on your behalf; nothing bypasses them.",
      f: "All SDKs and the CLI use the same public service APIs.",
      g: "CloudShell comes with the AWS CLI preinstalled and pre-authenticated.",
      h: "The AWS Console Mobile Application supports iOS and Android.",
    },
    referenceUrl: "https://docs.aws.amazon.com/cli/latest/userguide/cli-chap-welcome.html",
    referenceLabel: "What is the AWS Command Line Interface?",
    consoleUrl: "https://ap-southeast-1.console.aws.amazon.com/cloudshell/home?region=ap-southeast-1",
    consoleLabel: "AWS CloudShell",
