    id: "tech257",
    domain: "cloud-technology-and-services",
    text: "During a product launch, an operations team's Auto Scaling group fails to add more instances and the error says the account has reached its On-Demand vCPU limit for that instance family in the Region. The team wants to see the current limit and formally request a higher value. Which service should it use?",
    options: [
      { id: "a", text: "AWS Service Quotas" },
      { id: "b", text: "AWS Budgets" },
      { id: "c", text: "AWS Config" },
      { id: "d", text: "Amazon CloudWatch Logs" },
      { id: "e", text: "AWS License Manager" },
      { id: "f", text: "AWS Cost Explorer" },
      { id: "g", text: "AWS Systems Manager Patch Manager" },
      { id: "h", text: "AWS Resource Access Manager" },
    ],
    correctOptionIds: ["a"],
    explanation: "AWS Service Quotas is the central console and API for viewing the quotas (formerly called limits) that apply to your account for each service in each Region and for requesting increases for adjustable quotas. EC2 On-Demand instance limits are expressed in vCPUs per instance family, and a request can be submitted directly from Service Quotas without opening a support case. Trusted Advisor also flags quotas that are close to their limit, but Service Quotas is where you request the change.",
    optionRationale: {
      a: "Correct. Service Quotas shows applied quotas and lets you request increases.",
      b: "Budgets tracks spending and usage against thresholds; it does not manage service limits.",
      c: "Config records and evaluates resource configuration; it does not change quotas.",
      d: "CloudWatch Logs stores log data and cannot raise account limits.",
      e: "License Manager tracks software license usage, not AWS service quotas.",
      f: "Cost Explorer visualizes costs and usage; it has no quota management.",
      g: "Patch Manager applies OS patches to managed instances.",
      h: "RAM shares resources like subnets across accounts; it does not adjust limits.",
    },
    referenceUrl: "https://docs.aws.amazon.com/servicequotas/latest/userguide/intro.html",
    referenceLabel: "What is Service Quotas?",
    consoleUrl: "https://ap-southeast-1.console.aws.amazon.com/servicequotas/home/services/ec2/quotas?region=ap-southeast-1",
    consoleLabel: "Service Quotas > Amazon EC2",
    diagram: "flowchart LR\n  ASG[Auto Scaling group] -->|launch fails| Err[VcpuLimitExceeded]\n  Err --> SQ[Service Quotas\nEC2 > Running On-Demand Standard instances]\n  SQ -->|current: 64 vCPUs| View[View applied quota]\n  SQ -->|request 256 vCPUs| Req[Quota increase request]\n  Req -->|approved| ASG",
    cliExample: {
      description: "Show the applied On-Demand Standard instance vCPU quota for EC2 in Singapore",
      command: "aws service-quotas get-service-quota --region ap-southeast-1 --service-code ec2 --quota-code L-1216C47A --query 'Quota.{Name:QuotaName,Value:Value,Unit:Unit,Adjustable:Adjustable}'",
      sampleOutput:
        "{\n  \"Name\": \"Running On-Demand Standard (A, C, D, H, I, M, R, T, Z) instances\",\n  \"Value\": 64.0,\n  \"Unit\": \"None\",\n  \"Adjustable\": true\n}",
    },
